window.__finlexDocLoaded(10057,{"id":10057,"articles":[{"id":1000152,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Overarching global standard for limited and reasonable sustainability assurance engagements across all sustainability reporting frameworks (including IFRS S1/S2), effective for periods beginning on or after 15 Dec 2026.","seq":0},{"id":1000153,"no":"ISSA 5000 (Eff. Dec 2026)","heading":"Sustainability Assurance: Limited vs. Reasonable & Value Chain","text":"• Profession-agnostic, framework-neutral global standard for sustainability assurance engagements (applicable to IFRS S1/S2, ESRS, GRI, etc.) effective for periods beginning on or after 15 Dec 2026.\n• Covers both Limited Assurance (primarily inquiry and analytical procedures) and Reasonable Assurance (tests of controls and substantive procedures), addressing double vs. financial materiality, forward-looking estimates, value chain data, and fraud/greenwashing risks.\n• Preconditions: requires firm quality management at least as demanding as ISQM 1 and ethical/independence requirements at least as demanding as IESBA Part 5 (IESSA) (converged with China Sustainability Assurance Standard No. 6101).","seq":1},{"id":1000154,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: upcoming. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 4 (ISSA 5000)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
